{
  "findings": [
    {
      "check_id": "CKV_AWS_389",
      "title": "Launch configuration assigns public IP address",
      "resource": "aws_launch_configuration.lc",
      "severity": "MEDIUM",
      "explanation": "The resource explicitly sets associate_public_ip_address to true, exposing instances directly to the internet. This increases the attack surface and should be disabled unless strictly necessary for specific use cases not implied here."
    },
    {
      "check_id": "CKV_AWS_79",
      "title": "Instance Metadata Service (IMDS) v1 is enabled by default",
      "resource": "aws_launch_configuration.lc",
      "severity": "MEDIUM",
      "explanation": "The launch configuration does not configure metadata_options, meaning IMDSv1 remains enabled. IMDSv1 is vulnerable to SSRF attacks; enforcing IMDSv2 via http_tokens = 'required' mitigates this risk."
    },
    {
      "check_id": "CKV_AWS_8",
      "title": "EBS volumes are not encrypted at rest",
      "resource": "aws_launch_configuration.lc",
      "severity": "MEDIUM",
      "explanation": "The root_block_device block is missing or does not specify encrypted = true. Data stored on the instance's EBS volume is unencrypted, violating security best practices for data at rest protection."
    }
  ],
  "patched_code": "resource \"aws_launch_configuration\" \"lc\" {\n  name          = \"test_ecs\"\n  image_id      = data.aws_ami.amazon_linux.id\n  instance_type = \"t2.micro\"\n  lifecycle {\n    create_before_destroy = true\n  }\n  iam_instance_profile        = aws_iam_instance_profile.ecs_service_role.name\n  key_name                    = var.key_name\n  security_groups             = [aws_security_group.ec2-sg.id]\n  associate_public_ip_address = false\n  user_data                   = <<EOF\nsudo apt-get update\nsudo echo \"ECS_CLUSTER=${var.cluster_name}\" >> /etc/ecs/ecs.config\nEOF\n\n  metadata_options {\n    http_endpoint = \"enabled\"\n    http_tokens   = \"required\"\n  }\n\n  root_block_device {\n    encrypted = true\n  }\n}",
  "fix_summary": "Disabled public IP association by setting associate_public_ip_address to false. Added metadata_options to enforce IMDSv2 (http_tokens = required). Added root_block_device with encrypted = true to ensure data at rest encryption."
}
